/// 🌲️ Admits the real retained page tree before any partition graph allocation.
pub fn admitted_first_page(snapshot: &PdfSnapshot) -> Option<ObjRef> {
    fn entry<'a>(value: &'a PdfObject, key: &str) -> Option<&'a PdfObject> {
        let entries = match value { PdfObject::Dict(entries) => entries, _ => return None };
        let mut values = entries.iter().filter(|entry| entry.key == key);
        let value = &values.next()?.value;
        if values.next().is_some() { return None; }
        Some(value)
    }
    let mut ids = std::collections::HashSet::new();
    if snapshot.objects.iter().any(|entry| !ids.insert(entry.id)) { return None; }
    let roots = snapshot.trailer.iter().filter(|entry| entry.key == "Root").collect::<Vec<_>>();
    if roots.len() != 1 { return None; }
    let catalog = object(snapshot, roots[0].value.as_ref()?)?;
    if entry(catalog, "Type")?.as_name() != Some("Catalog") { return None; }
    let tree = entry(catalog, "Pages")?.as_ref()?;
    if entry(object(snapshot, tree)?, "Type")?.as_name() != Some("Pages") { return None; }
    let mut leaves = Vec::new();
    let mut pending = vec![(tree, None, false)];
    let mut seen = std::collections::HashSet::new();
    let mut counts = std::collections::HashMap::<ObjRef, usize>::new();
    while let Some((reference, parent, finishing)) = pending.pop() {
        let value = object(snapshot, reference)?;
        let kind = entry(value, "Type")?.as_name()?;
        if finishing {
            let mut count = 0usize;
            for child in entry(value, "Kids")?.as_array()? { count = count.checked_add(*counts.get(&child.as_ref()?)?)?; }
            let PdfObject::Int(declared) = entry(value, "Count")? else { return None; };
            if *declared != i64::try_from(count).ok()? { return None; }
            counts.insert(reference, count);
            continue;
        }
        if !seen.insert(reference) { return None; }
        if let Some(parent) = parent { if entry(value, "Parent")?.as_ref()? != parent { return None; } }
        match kind {
            "Page" => { leaves.push(reference); counts.insert(reference, 1); }
            "Pages" => {
                pending.push((reference, parent, true));
                for child in entry(value, "Kids")?.as_array()?.iter().rev() { pending.push((child.as_ref()?, Some(reference), false)); }
            }
            _ => return None,
        }
    }
    if leaves.len() != snapshot.pages.len() { return None; }
    for (reference, typed) in leaves.iter().zip(&snapshot.pages) {
        let media = entry(object(snapshot, *reference)?, "MediaBox")?.as_array()?;
        if media.len() != 4 { return None; }
        for (raw, expected) in media.iter().zip(&typed.media_box) {
            let number = match raw {
                PdfObject::Int(value) => *value as f64,
                PdfObject::Real(value) => format!("{}{}e-{}", if value.negative { "-" } else { "" }, value.coefficient, value.scale).parse::<f64>().ok()?,
                _ => return None,
            };
            if number.to_bits() != expected.to_bits() { return None; }
        }
    }
    leaves.first().copied()
}

